/* 학습 해설
 * Alternative likely capability·기본 branch를 NOP으로 치환
 * CPU feature별 runtime instruction 치환을 descriptor·relocation·설정·callback·assembly section·제어 흐름으로 이해합니다.
 * likely helper는 먼저 cpucap_is_possible이 false면false를 반환합니다. 그 밖에는 기본 branch가 l_no로 가서false이고 패치되면 branch가NOP이 되어true로 흐릅니다. BUILD_VDSO는 일반대체, kernel은 NOP 생성 callback을 사용합니다. immediate i 제약은 capability가 assembly 입력의 상수여야 함을 요구합니다.
 * fixture는 possible0/1·VDSO0/1·sanitizer0/1에서 아직 패치하지 않은false 경로를 실행했습니다. 실제 기능 발견·patch후true·SMP를 실행 검증한 결과로 해석하지 않습니다.
 */
alternative_has_cap_likely(const unsigned long cpucap)
{
	if (!cpucap_is_possible(cpucap))
		return false;

	asm goto(
#ifdef BUILD_VDSO
	ALTERNATIVE("b	%l[l_no]", "nop", %[cpucap])
#else
	ALTERNATIVE_CB("b	%l[l_no]", %[cpucap], alt_cb_patch_nops)
#endif
	:
	: [cpucap] "i" (cpucap)
	:
	: l_no);

	return true;
l_no:
	return false;
}

static __always_inline bool
alternative_has_cap_unlikely(const unsigned long cpucap)
{
	if (!cpucap_is_possible(cpucap))
		return false;

/* 학습 해설
 * Alternative unlikely capability·NOP을 branch로 치환
 * CPU feature별 runtime instruction 치환을 descriptor·relocation·설정·callback·assembly section·제어 흐름으로 이해합니다.
 * unlikely helper는 impossible capability에서false, 일반 기본NOP 뒤에도false입니다. capability 적용 시NOP을 l_yes로 향하는 branch로 바꾸어true가 됩니다. asm goto는 assembler 명령이 C label로 이동할 수 있게 알려주며 output operand가 없는 이 인터페이스는 C 제어 흐름과 instruction patch를 연결합니다.
 * likely와unlikely의 기본명령·대체명령·true/false label을 나란히 적습니다. branch의 l_yes PC-relative relocation은 실제 patch engine의 위치 조정과 연결해 읽습니다.
 */
alternative_has_cap_unlikely(const unsigned long cpucap)
{
	if (!cpucap_is_possible(cpucap))
		return false;

	asm goto(
	ALTERNATIVE("nop", "b	%l[l_yes]", %[cpucap])
	:
	: [cpucap] "i" (cpucap)
	:
	: l_yes);

	return false;
l_yes:
	return true;
}

#endif /* __ASSEMBLY__ */

#endif /* __ASM_ALTERNATIVE_MACROS_H */

